CREATE TABLE vendors (
  vendor_id VARCHAR(255) NOT NULL,
  vendor_code VARCHAR(255) NOT NULL,
  vendor_name VARCHAR(255) NOT NULL,
  tax_id VARCHAR(255) NOT NULL,
  state VARCHAR(255) NOT NULL,
  categories VARCHAR(255) NOT NULL,
  payment_terms VARCHAR(255) NOT NULL,
  payment_terms_days INT NOT NULL,
  invoice_channel VARCHAR(255) NOT NULL,
  payment_method VARCHAR(255) NOT NULL,
  status VARCHAR(255) NOT NULL,
  onboarded_date DATE NOT NULL,
  closed_date DATE,
  PRIMARY KEY (vendor_id),
  UNIQUE (vendor_code),
  UNIQUE (vendor_name),
  UNIQUE (tax_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE purchase_orders (
  po_id VARCHAR(255) NOT NULL,
  vendor_id VARCHAR(255) NOT NULL,
  po_date DATE NOT NULL,
  requester_id VARCHAR(255) NOT NULL,
  buyer_id VARCHAR(255) NOT NULL,
  cost_center VARCHAR(255) NOT NULL,
  currency VARCHAR(255) NOT NULL,
  line_count INT NOT NULL,
  subtotal_amount DECIMAL(14,2) NOT NULL,
  tax_amount DECIMAL(14,2) NOT NULL,
  total_amount DECIMAL(14,2) NOT NULL,
  status VARCHAR(255) NOT NULL,
  PRIMARY KEY (po_id),
  FOREIGN KEY (vendor_id) REFERENCES vendors(vendor_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE purchase_order_lines (
  po_line_id VARCHAR(255) NOT NULL,
  po_id VARCHAR(255) NOT NULL,
  line_number INT NOT NULL,
  sku VARCHAR(255) NOT NULL,
  description VARCHAR(255) NOT NULL,
  uom VARCHAR(255) NOT NULL,
  quantity_ordered INT NOT NULL,
  unit_price DECIMAL(14,2) NOT NULL,
  tax_code VARCHAR(255) NOT NULL,
  line_amount DECIMAL(14,2) NOT NULL,
  line_tax_amount DECIMAL(14,2) NOT NULL,
  quantity_received INT NOT NULL,
  receipt_status VARCHAR(255) NOT NULL,
  PRIMARY KEY (po_line_id),
  FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE purchase_order_events (
  event_id VARCHAR(255) NOT NULL,
  po_id VARCHAR(255) NOT NULL,
  sequence INT NOT NULL,
  event_date DATE NOT NULL,
  from_status VARCHAR(255),
  to_status VARCHAR(255) NOT NULL,
  source_ref VARCHAR(255) NOT NULL,
  PRIMARY KEY (event_id),
  FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE goods_receipts (
  grn_id VARCHAR(255) NOT NULL,
  po_id VARCHAR(255) NOT NULL,
  vendor_id VARCHAR(255) NOT NULL,
  receipt_date DATE NOT NULL,
  warehouse VARCHAR(255) NOT NULL,
  line_count INT NOT NULL,
  PRIMARY KEY (grn_id),
  FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id),
  FOREIGN KEY (vendor_id) REFERENCES vendors(vendor_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE goods_receipt_lines (
  grn_line_id VARCHAR(255) NOT NULL,
  grn_id VARCHAR(255) NOT NULL,
  po_line_id VARCHAR(255) NOT NULL,
  quantity_received INT NOT NULL,
  PRIMARY KEY (grn_line_id),
  FOREIGN KEY (grn_id) REFERENCES goods_receipts(grn_id),
  FOREIGN KEY (po_line_id) REFERENCES purchase_order_lines(po_line_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE invoices (
  invoice_id VARCHAR(255) NOT NULL,
  document_id VARCHAR(255) NOT NULL,
  vendor_id VARCHAR(255) NOT NULL,
  po_id VARCHAR(255),
  vendor_invoice_number VARCHAR(255) NOT NULL,
  invoice_date DATE NOT NULL,
  received_date DATE NOT NULL,
  channel VARCHAR(255) NOT NULL,
  currency VARCHAR(255) NOT NULL,
  line_count INT NOT NULL,
  subtotal_amount DECIMAL(14,2) NOT NULL,
  tax_amount DECIMAL(14,2) NOT NULL,
  total_amount DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (invoice_id),
  UNIQUE (document_id),
  FOREIGN KEY (vendor_id) REFERENCES vendors(vendor_id),
  FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE invoice_lines (
  invoice_line_id VARCHAR(255) NOT NULL,
  invoice_id VARCHAR(255) NOT NULL,
  line_number INT NOT NULL,
  po_line_id VARCHAR(255),
  sku VARCHAR(255) NOT NULL,
  description VARCHAR(255) NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(14,2) NOT NULL,
  tax_code VARCHAR(255) NOT NULL,
  line_amount DECIMAL(14,2) NOT NULL,
  line_tax_amount DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (invoice_line_id),
  FOREIGN KEY (invoice_id) REFERENCES invoices(invoice_id),
  FOREIGN KEY (po_line_id) REFERENCES purchase_order_lines(po_line_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE approvals (
  approval_id VARCHAR(255) NOT NULL,
  invoice_id VARCHAR(255) NOT NULL,
  level INT NOT NULL,
  approver_role VARCHAR(255) NOT NULL,
  approver_id VARCHAR(255) NOT NULL,
  policy_tier INT NOT NULL,
  decision VARCHAR(255) NOT NULL,
  decided_date DATE NOT NULL,
  PRIMARY KEY (approval_id),
  FOREIGN KEY (invoice_id) REFERENCES invoices(invoice_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE payments (
  payment_id VARCHAR(255) NOT NULL,
  invoice_id VARCHAR(255) NOT NULL,
  vendor_id VARCHAR(255) NOT NULL,
  amount DECIMAL(14,2) NOT NULL,
  currency VARCHAR(255) NOT NULL,
  method VARCHAR(255) NOT NULL,
  due_date DATE NOT NULL,
  scheduled_date DATE NOT NULL,
  status VARCHAR(255) NOT NULL,
  paid_date DATE,
  PRIMARY KEY (payment_id),
  UNIQUE (invoice_id),
  FOREIGN KEY (invoice_id) REFERENCES invoices(invoice_id),
  FOREIGN KEY (vendor_id) REFERENCES vendors(vendor_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE ground_truth (
  invoice_id VARCHAR(255) NOT NULL,
  scenario VARCHAR(255) NOT NULL,
  sub_scenario VARCHAR(255) NOT NULL,
  variant VARCHAR(255),
  issue_type VARCHAR(255),
  target_line VARCHAR(255),
  injected_detail VARCHAR(255),
  duplicate_of_invoice_id VARCHAR(255),
  expected_exceptions VARCHAR(255),
  expected_primary_exception VARCHAR(255),
  expected_match_status VARCHAR(255) NOT NULL,
  expected_route_queue VARCHAR(255),
  expected_approval_roles VARCHAR(255),
  expected_payment_ready VARCHAR(5) NOT NULL,
  PRIMARY KEY (invoice_id),
  FOREIGN KEY (invoice_id) REFERENCES invoices(invoice_id),
  FOREIGN KEY (duplicate_of_invoice_id) REFERENCES invoices(invoice_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

